# Function to process collection data
def process_collection(source_collection, target_collection_name, include_gt_code=False):
    target_collection = manage_skus_db[target_collection_name]
    
    # Clear existing data in target collection
    target_collection.delete_many({})
    
    # Fetch data from source collection
    cursor = db[source_collection].find()
    
    for doc in cursor:
        # Prepare new document
        new_doc = {
            "modelno": doc.get("modelno"),
            "status": "inactive" if doc.get("modelno") == "506" else "active",
            "timestamp": current_timestamp,
            "UserID": 1,
            "comment": []
        }
        
        # Include gt_code for channel_no_tbm collection
        if include_gt_code:
            new_doc["gt_code"] = doc.get("gt_code", [])
        
        # Insert into target collection
        target_collection.insert_one(new_doc)

# Process each collection
process_collection("channel_no_curing", "curing_modelno")
process_collection("channel_no_tbm", "tbm_gtcodes", include_gt_code=True)
process_collection("channel_no_ufm", "ufm_modelno")

